/// Applies a transient composition-owned entity override before authored camera arbitration.
///
/// The override may select a disabled standby Camera2D or Camera3D. A missing runtime entity
/// falls back to the normal enabled/priority contract, so stale Timeline bindings never black
/// out the Game View.
#[doc(hidden)]
pub fn select_game_camera_intent_with_override(
    candidates: impl IntoIterator<Item = GameCameraIntent>,
    override_target: Option<engine_ecs::Entity>,
) -> GameCameraSelection {
    let candidates = candidates.into_iter().collect::<Vec<_>>();
    if let Some(target) = override_target
        && let Some(candidate) = candidates.iter().copied().find(|candidate| candidate.entity == target)
    {
        return GameCameraSelection::Selected(candidate);
    }
    let mut enabled = candidates.into_iter().filter(|candidate| candidate.enabled);
    let Some(mut best) = enabled.next() else {
        return GameCameraSelection::None;
    };
    let mut tied = 1_usize;
    for candidate in enabled {
        if candidate.priority > best.priority {
            best = candidate;
            tied = 1;
        } else if candidate.priority == best.priority {
            tied += 1;
        }
    }
    if tied > 1 {
        GameCameraSelection::Ambiguous { priority: best.priority, count: tied }
    } else {
        GameCameraSelection::Selected(best)
    }
}
